﻿#!/usr/bin/env node
// CLI entry: starts the selected MCP transport (stdio by default).
import '../src/index.js';

export type ServerTransportKind = 'stdio' | 'http';

export interface ServerCliOptions {
  transport: ServerTransportKind;
  port?: number;
  path?: string;
  help: boolean;
}

function parsePort(value: string): number {
  if (!/^\d+$/.test(value)) throw new Error('--port must be an integer from 1 to 65535.');
  const port = Number(value);
  if (port < 1 || port > 65535) {
    throw new Error('--port must be an integer from 1 to 65535.');
  }
  return port;
}

function parseTransport(value: string): ServerTransportKind {
  if (value === 'stdio' || value === 'http') return value;
  throw new Error('--transport must be stdio or http.');
}

function readOptionValue(args: string[], index: number, name: string): string {
  const value = args[index + 1];
  if (!value || value.startsWith('--')) throw new Error(`${name} requires a value.`);
  return value;
}

export function parseServerCliOptions(
  args: string[],
  env: Record<string, string | undefined> = process.env
): ServerCliOptions {
  const envTransport = env.VRCHAT_MCP_TRANSPORT;
  let transport = envTransport ? parseTransport(envTransport.trim().toLowerCase()) : 'stdio';
  let port: number | undefined;
  let path: string | undefined;
  let help = false;

  for (let index = 0; index < args.length; index += 1) {
    const arg = args[index];
    if (arg === '--help' || arg === '-h') {
      help = true;
      continue;
    }
    if (arg === '--http') {
      transport = 'http';
      continue;
    }
    if (arg === '--transport') {
      transport = parseTransport(readOptionValue(args, index, '--transport'));
      index += 1;
      continue;
    }
    if (arg === '--port') {
      port = parsePort(readOptionValue(args, index, '--port'));
      index += 1;
      continue;
    }
    if (arg === '--path') {
      path = readOptionValue(args, index, '--path');
      if (
        path.length < 2 ||
        path.length > 128 ||
        !/^\/[A-Za-z0-9._~/-]*$/.test(path) ||
        /^\/healthz\/?$/i.test(path)
      ) {
        throw new Error('--path must be a non-reserved URL path using safe characters.');
      }
      index += 1;
      continue;
    }
    throw new Error(`Unknown option: ${arg}`);
  }

  if (transport !== 'http' && (port !== undefined || path !== undefined)) {
    throw new Error('--port and --path require --transport http.');
  }
  return { transport, port, path, help };
}

export function serverCliUsage(): string {
  return `Usage: vrchat-mcp [options]

Options:
  --transport <stdio|http>  Transport mode (default: stdio)
  --http                    Alias for --transport http
  --port <number>           HTTP port (default: 8765)
  --path <path>             HTTP MCP endpoint path (default: /mcp)
  --help                    Show this help

HTTP mode is loopback-only and requires VRCHAT_MCP_HTTP_BEARER_TOKEN.
`;
}

import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { parseServerCliOptions, serverCliUsage } from './cli.js';
import { getConfig } from './config/index.js';
import { logger } from './infra/logger.js';
import {
  createVrchatMcpServer,
  initializeRuntime,
  releaseVrchatMcpServer,
  shutdownRuntime,
} from './server.js';
import { startHttpTransport } from './transports/http.js';

async function main(): Promise<void> {
  const cli = parseServerCliOptions(process.argv.slice(2));
  if (cli.help) {
    process.stderr.write(serverCliUsage());
    return;
  }

  await initializeRuntime();

  if (cli.transport === 'stdio') {
    const server = await createVrchatMcpServer();
    const transport = new StdioServerTransport();
    transport.onclose = () => {
      releaseVrchatMcpServer(server);
      shutdownRuntime();
    };
    await server.connect(transport);
    installShutdownHandler(async () => {
      releaseVrchatMcpServer(server);
      await server.close();
      shutdownRuntime();
    });
    return;
  }

  const config = getConfig();
  const bearerToken = process.env.VRCHAT_MCP_HTTP_BEARER_TOKEN ?? '';
  const handle = await startHttpTransport({
    port: cli.port ?? config.http.port,
    path: cli.path ?? config.http.path,
    bearerToken,
    maxSessions: config.http.maxSessions,
    rateLimitPerMinute: config.http.rateLimitPerMinute,
    sessionIdleTimeoutMs: config.http.sessionIdleTimeoutMs,
    serverFactory: createVrchatMcpServer,
    releaseServer: releaseVrchatMcpServer,
  });
  logger.info('MCP Streamable HTTP server listening.', {
    url: handle.url,
    transport: 'http',
  });
  installShutdownHandler(async () => {
    await handle.close();
    shutdownRuntime();
  });
}

function installShutdownHandler(close: () => Promise<void>): void {
  let shuttingDown = false;
  const shutdown = () => {
    if (shuttingDown) return;
    shuttingDown = true;
    void close()
      .catch((error: unknown) => {
        logger.error('Failed to shut down cleanly.', {
          message: error instanceof Error ? error.message : String(error),
        });
      })
      .finally(() => {
        process.exit(0);
      });
  };
  process.once('SIGINT', shutdown);
  process.once('SIGTERM', shutdown);
}

main().catch((error: unknown) => {
  logger.error('Fatal error starting server', {
    message: error instanceof Error ? error.message : String(error),
  });
  process.exit(1);
});

import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import pkg from '../package.json' with { type: 'json' };
import { authManager } from './auth/index.js';
import { getConfig } from './config/index.js';
import { logger } from './infra/logger.js';
import { registerResources } from './resources/index.js';
import { unregisterResourceSubscriptions } from './resources/subscriptions.js';
import { registerPipelineHandlers } from './services/pipeline/index.js';
import { pipelineManager } from './services/pipeline/manager.js';
import { registerAllTools } from './tools/registerAllTools.js';

let runtimeInitialization: Promise<void> | null = null;

function validateConfig(): void {
  const config = getConfig();
  const userAgent = config.api.userAgent?.trim();
  if (!userAgent || userAgent.startsWith('vrchat-mcp/')) {
    logger.warn('Using default user-agent. Set a descriptive UA in config (api.userAgent).');
  }
}

export async function initializeRuntime(): Promise<void> {
  runtimeInitialization ??= (async () => {
    validateConfig();
    await authManager.init();
    registerPipelineHandlers();
  })();
  await runtimeInitialization;
}

export async function createVrchatMcpServer(): Promise<McpServer> {
  const server = new McpServer({
    name: 'vrchat-mcp',
    version: pkg.version ?? '0.0.0',
  });
  registerResources(server);
  await registerAllTools(server);
  return server;
}

export function releaseVrchatMcpServer(server: McpServer): void {
  unregisterResourceSubscriptions(server);
}

export function shutdownRuntime(): void {
  pipelineManager.stop();
}

﻿import { CookieJar } from 'tough-cookie';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomBytes } from 'node:crypto';
import { EventEmitter } from 'node:events';
import { URL } from 'node:url';
import { getConfig } from '../config/index.js';
import { logger } from '../infra/logger.js';
import { getCookieStore } from './cookieStore.js';

const MAX_LOGIN_BODY_BYTES = 16 * 1024;

export interface AuthStatus extends Record<string, unknown> {
  loggedIn: boolean;
}

class AuthError extends Error {
  kind?: 'totp' | 'emailOtp' | 'unknown';
  isChallenge: boolean;
  constructor(
    message: string,
    kind?: 'totp' | 'emailOtp' | 'unknown',
    options: { isChallenge?: boolean } = {}
  ) {
    super(message);
    this.name = 'AuthError';
    this.kind = kind;
    this.isChallenge = options.isChallenge === true;
  }
}

class BodyTooLargeError extends Error {
  constructor() {
    super('Login request body is too large.');
    this.name = 'BodyTooLargeError';
  }
}

interface LoginSubmission {
  usernameInput: string;
  passwordInput: string;
  totp?: string;
  emailOtp?: string;
}

function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function cleanInput(value: string | null): string | undefined {
  const trimmed = value?.trim();
  if (!trimmed) return undefined;
  return trimmed;
}

function parseLoginSubmission(params: URLSearchParams): LoginSubmission {
  const usernameInput = params.get('username') ?? '';
  const passwordInput = params.get('password') ?? '';
  const factorKind = params.get('factorKind') ?? '';
  const code = cleanInput(params.get('code'));
  const directTotp = cleanInput(params.get('totp'));
  const directEmailOtp = cleanInput(params.get('emailOtp'));
  return {
    usernameInput,
    passwordInput,
    totp: directTotp ?? (factorKind === 'totp' ? code : undefined),
    emailOtp: directEmailOtp ?? (factorKind === 'emailOtp' ? code : undefined),
  };
}

function loginUserAgent(): string {
  return getConfig().api.userAgent;
}

function isAllowedLoopbackHost(host: string, expectedPort: number): boolean {
  let parsed: URL;
  try {
    parsed = new URL(`http://${host}`);
  } catch {
    return false;
  }
  if (
    host.includes('@') ||
    parsed.username.length > 0 ||
    parsed.password.length > 0 ||
    parsed.pathname !== '/' ||
    parsed.search ||
    parsed.hash
  ) {
    return false;
  }

  const hostname = parsed.hostname.toLowerCase();
  const port = Number(parsed.port || '80');
  return (
    port === expectedPort &&
    (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]')
  );
}

function isAllowedLoopbackOrigin(origin: string, expectedPort: number): boolean {
  let parsed: URL;
  try {
    parsed = new URL(origin);
  } catch {
    return false;
  }
  if (
    origin.includes('@') ||
    parsed.username.length > 0 ||
    parsed.password.length > 0 ||
    parsed.pathname !== '/' ||
    parsed.search ||
    parsed.hash
  ) {
    return false;
  }

  const hostname = parsed.hostname.toLowerCase();
  const port = Number(parsed.port || '80');
  return (
    parsed.protocol === 'http:' &&
    port === expectedPort &&
    (hostname === 'localhost' || hostname === '127.0.0.1' || hostname === '[::1]')
  );
}

class AuthManager {
  private jar = new CookieJar();
  private server: ReturnType<typeof createServer> | null = null;
  private serverToken: string | null = null;
  private port: number | null = null;
  private loggedIn = false;
  private pendingCreds: { username: string; password: string } | null = null;
  private store = getCookieStore();
  private events = new EventEmitter();
  private loginQueue: Promise<unknown> = Promise.resolve();

  /**
   * Runs headless and browser logins one at a time, so each login's jar, flags, persist, and
   * status emit land together. The queue advances whether a login resolves or rejects.
   */
  private serializeLogin<T>(fn: () => Promise<T>): Promise<T> {
    const run = this.loginQueue.then(fn, fn);
    this.loginQueue = run.catch(() => undefined);
    return run;
  }

  async init() {
    const loaded = await this.store.load();
    if (loaded) {
      this.jar = loaded;
      this.loggedIn = await this.hasAuthCookie();
    }
    this.emitStatus();
  }

  private async hasAuthCookie(): Promise<boolean> {
    const cookies = await this.jar.getCookies('https://api.vrchat.cloud');
    return cookies.some((c) => c.key === 'auth' || c.key === 'twoFactorAuth');
  }

  clearCookies() {
    this.jar = new CookieJar();
  }

  getCookieHeader(url: string): Promise<string> {
    return this.jar.getCookieString(url);
  }

  async getCookieValue(
    name: string,
    url = 'https://api.vrchat.cloud'
  ): Promise<string | undefined> {
    const cookies = await this.jar.getCookies(url);
    const match = cookies.find((cookie) => cookie.key === name);
    return match?.value;
  }

  async setCookiesFromResponse(url: string, setCookieHeaders: string[]) {
    for (const setCookie of setCookieHeaders) {
      await this.jar.setCookie(setCookie, url);
    }
    await this.persist();
  }

  getStatus(): AuthStatus {
    return { loggedIn: this.loggedIn };
  }

  onStatusChange(listener: (status: AuthStatus) => void): () => void {
    this.events.on('status', listener);
    return () => this.events.off('status', listener);
  }

  private emitStatus() {
    this.events.emit('status', this.getStatus());
  }

  async logout() {
    this.loggedIn = false;
    this.clearCookies();
    this.pendingCreds = null;
    await this.store.clear();
    if (this.server) {
      this.server.close();
      this.server = null;
      this.port = null;
    }
    this.emitStatus();
  }

  /** Non-interactive login used by automatic re-login (see autoLogin.ts). */
  loginHeadless(username: string, password: string, totp: string): Promise<void> {
    return this.serializeLogin(async () => {
      try {
        await this.performLogin(username, password, totp);
      } catch (err) {
        this.loggedIn = false;
        this.emitStatus();
        throw err;
      }
      this.loggedIn = true;
      await this.persist();
      this.emitStatus();
    });
  }

  async startLoginServer(): Promise<{ url: string; token: string }> {
    if (this.server) {
      return {
        url: `http://127.0.0.1:${this.port}/?token=${encodeURIComponent(this.serverToken!)}`,
        token: this.serverToken!,
      };
    }
    const token = randomBytes(16).toString('hex');
    this.serverToken = token;

    this.server = createServer((req, res) => {
      this.handleRequest(req, res).catch((err) => {
        logger.error('auth server error', { message: (err as Error).message });
        res.statusCode = 500;
        res.end('Internal server error');
      });
    });

    await new Promise<void>((resolve) => {
      this.server!.listen(0, '127.0.0.1', () => resolve());
    });
    const address = this.server.address();
    const port = typeof address === 'object' && address ? address.port : 0;
    this.port = port;
    return { url: `http://127.0.0.1:${port}/?token=${encodeURIComponent(token)}`, token };
  }

  private async parseBody(req: IncomingMessage): Promise<URLSearchParams> {
    const chunks: Buffer[] = [];
    let total = 0;
    for await (const chunk of req) {
      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      total += buf.length;
      if (total > MAX_LOGIN_BODY_BYTES) {
        req.resume();
        throw new BodyTooLargeError();
      }
      chunks.push(buf);
    }
    const body = Buffer.concat(chunks).toString('utf8');
    return new URLSearchParams(body);
  }

  private renderForm(
    res: ServerResponse,
    token: string,
    options: {
      error?: string;
      notice?: string;
      stage?: 'initial' | 'totp' | 'emailOtp';
      usernameHint?: string;
    } = {}
  ) {
    const stage = options.stage ?? 'initial';
    const showOtp = stage === 'totp' || stage === 'emailOtp';
    const codeLabel = stage === 'emailOtp' ? 'Email verification code' : 'Authenticator code';
    const codeHelp =
      stage === 'emailOtp'
        ? 'Check your VRChat account email for the one-time code.'
        : 'Open your authenticator app and enter the current six-digit code.';
    const usernameHint = options.usernameHint ? escapeHtml(options.usernameHint) : '';
    const error = options.error ? escapeHtml(options.error) : undefined;
    const notice = options.notice ? escapeHtml(options.notice) : undefined;
    const encodedToken = encodeURIComponent(token);
    const actionsClass = showOtp ? 'actions two' : 'actions';
    this.renderPage(
      res,
      `<div class="brand"><h1>VRChat MCP Login</h1></div>
      ${error ? `<p class="error">${error}</p>` : ''}
      ${notice ? `<p class="notice">${notice}</p>` : ''}
      ${
        showOtp
          ? `<p>2FA is required${usernameHint ? ` for <span class="account">${usernameHint}</span>` : ''}. ${codeHelp}</p>`
          : '<p>Sign in to VRChat to let the MCP server make authenticated requests on your behalf.</p>'
      }
      <form method="POST" action="/submit?token=${encodedToken}">
        ${
          showOtp
            ? `<input type="hidden" name="factorKind" value="${stage}" /><label>${codeLabel}<input name="code" inputmode="numeric" autocomplete="one-time-code" required autofocus /></label>`
            : '<label>Username or email<input name="username" autocomplete="username" required autofocus /></label><label>Password<input name="password" type="password" autocomplete="current-password" required /></label>'
        }
        <div class="${actionsClass}">
          <button type="submit">${showOtp ? 'Verify' : 'Login'}</button>
          ${showOtp ? `<a class="link-button" href="/reset?token=${encodedToken}">Use another account</a>` : ''}
        </div>
      </form>`
    );
  }

  private renderSuccess(res: ServerResponse) {
    this.renderPage(
      res,
      `<div class="brand"><h1>Login successful</h1></div>
      <p class="notice">You're logged in.</p>
      <p>You can close this window and return to your MCP client.</p>`
    );
  }

  private renderAuthError(
    res: ServerResponse,
    token: string,
    err: unknown,
    username: string
  ): boolean {
    if (!(err instanceof AuthError) || !err.kind || err.kind === 'unknown') {
      return false;
    }

    const isChallenge = err.isChallenge;
    const notice =
      err.kind === 'emailOtp' ? 'Email verification required' : 'Authenticator code required';
    this.renderForm(res, token, {
      error: isChallenge ? undefined : err.message,
      notice: isChallenge ? notice : undefined,
      stage: err.kind === 'totp' ? 'totp' : 'emailOtp',
      usernameHint: username,
    });
    return true;
  }

  private renderPage(res: ServerResponse, body: string) {
    res.setHeader('content-type', 'text/html; charset=utf-8');
    // 'no-referrer' makes browsers send `Origin: null` on the login form POST
    // (Fetch: append-a-request-Origin-header), which our own origin check rejects.
    // 'same-origin' keeps the token out of cross-origin Referers and preserves Origin.
    res.setHeader('referrer-policy', 'same-origin');
    res.setHeader('x-frame-options', 'DENY');
    res.setHeader(
      'content-security-policy',
      "default-src 'none'; style-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"
    );
    res.end(`<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>VRChat MCP Login</title>
    <style>
      :root { color-scheme: dark; font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
      * { box-sizing: border-box; }
      body { min-height: 100vh; margin: 0; display: grid; place-items: center; background: radial-gradient(circle at top left, #4f46e5 0, transparent 30%), linear-gradient(135deg, #0f172a, #111827 55%, #020617); color: #e5e7eb; }
      main { width: min(440px, calc(100vw - 32px)); padding: 32px; border: 1px solid rgba(148, 163, 184, 0.24); border-radius: 24px; background: rgba(15, 23, 42, 0.86); box-shadow: 0 24px 80px rgba(0, 0, 0, 0.45); backdrop-filter: blur(16px); }
      .brand { margin-bottom: 24px; }
      h1 { margin: 0; font-size: 1.45rem; line-height: 1.2; }
      p { color: #aebbd0; line-height: 1.5; }
      .error { padding: 12px 14px; border: 1px solid rgba(248, 113, 113, 0.45); border-radius: 14px; background: rgba(127, 29, 29, 0.35); color: #fecaca; }
      .notice { padding: 12px 14px; border: 1px solid rgba(103, 232, 249, 0.36); border-radius: 14px; background: rgba(8, 47, 73, 0.35); color: #cffafe; }
      label { display: grid; gap: 8px; margin: 16px 0; color: #dbeafe; font-weight: 650; }
      input { width: 100%; border: 1px solid rgba(148, 163, 184, 0.36); border-radius: 14px; padding: 12px 14px; background: rgba(2, 6, 23, 0.74); color: #f8fafc; font-size: 1rem; }
      input:focus { outline: 2px solid #22d3ee; outline-offset: 2px; }
      .actions { display: grid; grid-template-columns: 1fr; gap: 12px; margin-top: 22px; }
      .actions.two { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
      button, .link-button { min-height: 52px; display: inline-flex; align-items: center; justify-content: center; border: 0; border-radius: 16px; padding: 0 18px; background: #67e8f9; color: #082f49; font-weight: 800; line-height: 1.15; text-align: center; cursor: pointer; text-decoration: none; }
      .link-button { background: rgba(148, 163, 184, 0.18); color: #dbeafe; }
      .hint { margin: 0; font-size: 0.92rem; }
      .account { color: #f8fafc; font-weight: 800; }
      @media (max-width: 520px) { main { padding: 24px; } .actions.two { grid-template-columns: 1fr; } }
    </style>
  </head>
  <body>
    <main>
      ${body}
    </main>
  </body>
</html>`);
  }

  private getValidatedRequestContext(
    req: IncomingMessage,
    res: ServerResponse
  ): { urlObj: URL; token: string } | null {
    if (!this.serverToken || !this.port) {
      res.statusCode = 503;
      res.end('Auth server not ready');
      return null;
    }

    const host = req.headers.host;
    if (!host || !isAllowedLoopbackHost(host, this.port)) {
      res.statusCode = 403;
      res.end('Invalid host');
      return null;
    }

    const origin = req.headers.origin;
    if (origin && !isAllowedLoopbackOrigin(origin, this.port)) {
      res.statusCode = 403;
      res.end('Invalid origin');
      return null;
    }

    const urlObj = new URL(req.url ?? '/', `http://127.0.0.1:${this.port}`);
    const token = urlObj.searchParams.get('token');
    if (!token || token !== this.serverToken) {
      res.statusCode = 403;
      res.end('Invalid token');
      return null;
    }

    return { urlObj, token };
  }

  private async handleSubmit(req: IncomingMessage, res: ServerResponse, token: string) {
    const params = await this.parseBody(req);
    const submission = parseLoginSubmission(params);

    if (submission.usernameInput || submission.passwordInput) {
      this.pendingCreds = {
        username: submission.usernameInput,
        password: submission.passwordInput,
      };
    }

    const creds = this.pendingCreds ?? {
      username: submission.usernameInput,
      password: submission.passwordInput,
    };
    if (!creds.username || !creds.password) {
      this.renderForm(res, token, { error: 'Username and password are required.' });
      return;
    }

    await this.serializeLogin(async () => {
      try {
        await this.performLogin(
          creds.username,
          creds.password,
          submission.totp,
          submission.emailOtp
        );
        this.loggedIn = true;
        this.pendingCreds = null;
        await this.persist();
        this.emitStatus();
        res.statusCode = 200;
        this.renderSuccess(res);
      } catch (err) {
        this.loggedIn = false;
        if (this.renderAuthError(res, token, err, creds.username)) {
          return;
        }
        this.clearCookies();
        this.pendingCreds = null;
        const msg = err instanceof Error ? err.message : 'Login failed';
        this.renderForm(res, token, { error: msg });
      }
    });
  }

  private async handleRequest(req: IncomingMessage, res: ServerResponse) {
    const context = this.getValidatedRequestContext(req, res);
    if (!context) return;
    const { urlObj, token } = context;

    if (req.method === 'GET' && urlObj.pathname === '/') {
      this.renderForm(res, token);
      return;
    }

    if (req.method === 'GET' && urlObj.pathname === '/reset') {
      this.loggedIn = false;
      this.pendingCreds = null;
      this.clearCookies();
      await this.store.clear();
      this.emitStatus();
      this.renderForm(res, token);
      return;
    }

    if (req.method === 'POST' && urlObj.pathname === '/submit') {
      try {
        await this.handleSubmit(req, res, token);
      } catch (err) {
        if (err instanceof BodyTooLargeError) {
          res.statusCode = 413;
          res.setHeader('Connection', 'close');
          res.end('Request body too large');
          return;
        }
        throw err;
      }
      return;
    }

    res.statusCode = 404;
    res.end('Not found');
  }

  private async performLogin(username: string, password: string, totp?: string, emailOtp?: string) {
    const basic = Buffer.from(`${username}:${password}`).toString('base64');
    const res1 = await fetch('https://api.vrchat.cloud/api/1/auth/user', {
      method: 'GET',
      headers: {
        authorization: `Basic ${basic}`,
        'user-agent': loginUserAgent(),
      },
    });

    const setCookies1 = res1.headers.getSetCookie?.() ?? [];
    await this.setCookiesFromResponse('https://api.vrchat.cloud', setCookies1);
    const body1 = (await res1.json().catch(() => ({}))) as any;
    const requires2fa = Array.isArray(body1?.requiresTwoFactorAuth)
      ? (body1.requiresTwoFactorAuth as string[])
      : [];

    if (requires2fa.length) {
      const cookieHeader = await this.getCookieHeader('https://api.vrchat.cloud');
      if (requires2fa.includes('totp')) {
        if (!totp) {
          throw new AuthError(
            '2FA required (TOTP). Enter the code from your authenticator app.',
            'totp',
            { isChallenge: true }
          );
        }
        const res2 = await fetch('https://api.vrchat.cloud/api/1/auth/twofactorauth/totp/verify', {
          method: 'POST',
          headers: {
            cookie: cookieHeader,
            'content-type': 'application/json',
            'user-agent': loginUserAgent(),
          },
          body: JSON.stringify({ code: totp }),
        });
        const setCookies2 = res2.headers.getSetCookie?.() ?? [];
        await this.setCookiesFromResponse('https://api.vrchat.cloud', setCookies2);
        if (res2.status !== 200) {
          throw new AuthError(`TOTP verify failed: ${res2.status}`, 'totp');
        }
        return;
      }

      if (requires2fa.includes('emailOtp')) {
        if (!emailOtp) {
          throw new AuthError(
            '2FA required (Email OTP). Check your email and enter the code.',
            'emailOtp',
            { isChallenge: true }
          );
        }
        const res2 = await fetch(
          'https://api.vrchat.cloud/api/1/auth/twofactorauth/emailotp/verify',
          {
            method: 'POST',
            headers: {
              cookie: cookieHeader,
              'content-type': 'application/json',
              'user-agent': loginUserAgent(),
            },
            body: JSON.stringify({ code: emailOtp }),
          }
        );
        const setCookies2 = res2.headers.getSetCookie?.() ?? [];
        await this.setCookiesFromResponse('https://api.vrchat.cloud', setCookies2);
        if (res2.status !== 200) {
          throw new AuthError(`Email OTP verify failed: ${res2.status}`, 'emailOtp');
        }
        return;
      }

      throw new AuthError(`2FA required (${requires2fa.join(', ')}).`, 'unknown');
    }

    if (res1.status === 200) {
      return;
    }

    throw new Error(`Login failed: ${res1.status}`);
  }

  private async persist() {
    try {
      await this.store.save(this.jar);
    } catch (err) {
      logger.warn('Failed to persist cookies', { message: (err as Error).message });
    }
  }
}

export const authManager = new AuthManager();

import { readFileSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { z } from 'zod';
import pkg from '../../package.json' with { type: 'json' };
import defaultsJson from './defaults.json' with { type: 'json' };

const DISABLED_ALLOWLIST_VALUES = new Set(['', '0', 'false', 'no', 'off']);

const GeneratedToolConfigSchema = z
  .object({
    enabled: z.boolean(),
    operationIds: z.array(z.string()),
  })
  .strict();

const ConfigBaseSchema = z
  .object({
    api: z
      .object({
        baseUrl: z.string().min(1),
        userAgent: z.string().min(1),
      })
      .strict(),
    spec: z
      .object({
        url: z.string().min(1),
      })
      .strict(),
    logging: z
      .object({
        level: z.string().min(1),
      })
      .strict(),
    auth: z
      .object({
        cookieStore: z.enum(['memory', 'file', 'keychain']),
        cookieFile: z.string().min(1),
      })
      .strict(),
    writes: z
      .object({
        allow: z.boolean(),
      })
      .strict(),
    cache: z
      .object({
        enabled: z.boolean(),
        ttlSeconds: z
          .object({
            friends: z.number().int().positive(),
            userGroups: z.number().int().positive(),
            groups: z.number().int().positive(),
            notifications: z.number().int().positive(),
          })
          .strict(),
        staleTtlSeconds: z
          .object({
            friends: z.number().int().positive(),
            userGroups: z.number().int().positive(),
            groups: z.number().int().positive(),
            notifications: z.number().int().positive(),
          })
          .strict(),
      })
      .strict(),
    pipeline: z
      .object({
        enabled: z.boolean(),
        url: z.string().min(1),
        reconnectMs: z.number().int().positive(),
        changeBuffer: z.number().int().positive(),
        userAgent: z.string(),
      })
      .strict(),
    groups: z
      .object({
        allowlist: z.array(z.string()),
      })
      .strict(),
    uploads: z
      .object({
        allowedRoots: z.array(z.string().min(1)),
      })
      .strict(),
    rawTools: z
      .object({
        enabled: z.boolean(),
      })
      .strict(),
    generatedReadTools: GeneratedToolConfigSchema,
    generatedWriteTools: GeneratedToolConfigSchema,
    http: z
      .object({
        port: z.number().int().min(1).max(65535),
        path: z
          .string()
          .min(2)
          .max(128)
          .regex(/^\/[A-Za-z0-9._~/-]*$/, 'HTTP path contains unsupported characters.')
          .refine((value) => !/^\/healthz\/?$/i.test(value), 'HTTP path /healthz is reserved.'),
        maxSessions: z.number().int().min(1).max(100),
        rateLimitPerMinute: z.number().int().min(1).max(10000),
        sessionIdleTimeoutMs: z.number().int().min(1).max(86_400_000),
      })
      .strict(),
    vrcx: z
      .object({
        enabled: z.boolean(),
        databasePath: z.string(),
        worldDbPath: z.string(),
      })
      .strict(),
  })
  .strict();

const ConfigSchema = ConfigBaseSchema.transform((config) => {
  const next = structuredClone(config);
  next.api.userAgent = applyTemplate(next.api.userAgent);
  next.pipeline.userAgent = next.pipeline.userAgent?.trim()
    ? applyTemplate(next.pipeline.userAgent)
    : next.api.userAgent;
  next.auth.cookieFile = expandHome(next.auth.cookieFile);
  next.uploads.allowedRoots = next.uploads.allowedRoots.map((root) => {
    const expanded = expandHome(root);
    if (!path.isAbsolute(expanded)) {
      throw new Error(`Upload root must be absolute: ${root}`);
    }
    return path.normalize(expanded);
  });
  next.vrcx.databasePath = expandHome(next.vrcx.databasePath);
  next.vrcx.worldDbPath = expandHome(next.vrcx.worldDbPath);
  return next;
});

export type Config = z.output<typeof ConfigSchema>;
type ConfigBase = z.infer<typeof ConfigBaseSchema>;
type DeepPartial<T> = {
  [K in keyof T]?: T[K] extends (infer U)[] ? U[] : T[K] extends object ? DeepPartial<T[K]> : T[K];
};

const defaults: Config = ConfigSchema.parse(defaultsJson);

const EnvString = z.preprocess((value) => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') return value;
  return value.trim();
}, z.string().min(1).optional());

const EnvLowercase = <T extends z.ZodTypeAny>(schema: T) =>
  z.preprocess((value) => {
    if (value === undefined) return undefined;
    if (typeof value !== 'string') return value;
    return value.trim().toLowerCase();
  }, schema);

const EnvBoolean = z.preprocess((value) => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') return value;
  const trimmed = value.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(trimmed)) return true;
  if (['0', 'false', 'no', 'off'].includes(trimmed)) return false;
  return value;
}, z.boolean().optional());

const EnvInteger = z.preprocess((value) => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!/^\d+$/.test(trimmed)) return value;
  return Number(trimmed);
}, z.number().int().optional());

const EnvAllowlist = z.preprocess((value) => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return [];
  if (DISABLED_ALLOWLIST_VALUES.has(trimmed.toLowerCase())) return [];
  return trimmed
    .split(/[,\n]/)
    .map((entry) => entry.trim())
    .filter(Boolean);
}, z.array(z.string()).optional());

const EnvPathList = z.preprocess((value) => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return [];
  return trimmed
    .split(new RegExp(`[${path.delimiter === ';' ? ';' : ':'}\\n]`))
    .map((entry) => entry.trim())
    .filter(Boolean);
}, z.array(z.string().min(1)).optional());

const EnvSchema = z
  .object({
    VRCHAT_MCP_API_BASE: EnvString,
    VRCHAT_MCP_USER_AGENT: EnvString,
    VRCHAT_MCP_SPEC_URL: EnvString,
    VRCHAT_MCP_LOG_LEVEL: EnvLowercase(z.enum(['debug', 'info', 'warn', 'error']).optional()),
    VRCHAT_MCP_COOKIE_STORE: EnvLowercase(z.enum(['memory', 'file', 'keychain']).optional()),
    VRCHAT_MCP_COOKIE_FILE: EnvString,
    VRCHAT_MCP_ALLOW_WRITES: EnvBoolean,
    VRCHAT_MCP_CACHE_ENABLED: EnvBoolean,
    VRCHAT_MCP_PIPELINE_ENABLED: EnvBoolean,
    VRCHAT_MCP_GROUP_ALLOWLIST: EnvAllowlist,
    VRCHAT_MCP_UPLOAD_ROOTS: EnvPathList,
    VRCHAT_MCP_ENABLE_RAW_CALL: EnvBoolean,
    VRCHAT_MCP_DISABLE_GENERATED_READ_TOOLS: EnvBoolean,
    VRCHAT_MCP_DISABLE_GENERATED_WRITE_TOOLS: EnvBoolean,
    VRCHAT_MCP_HTTP_PORT: EnvInteger,
    VRCHAT_MCP_HTTP_PATH: EnvString,
    VRCHAT_MCP_HTTP_MAX_SESSIONS: EnvInteger,
    VRCHAT_MCP_HTTP_RATE_LIMIT_PER_MINUTE: EnvInteger,
    VRCHAT_MCP_HTTP_SESSION_IDLE_TIMEOUT_MS: EnvInteger,
  })
  .strict();

type EnvValues = z.infer<typeof EnvSchema>;
const ENV_KEYS = Object.keys(EnvSchema.shape) as (keyof EnvValues)[];

let cachedBase: ConfigBase | null = null;
let cachedConfigPath: string | null = null;

function expandHome(value: string): string {
  if (!value) return value;
  if (value.startsWith('~/') || value === '~') {
    const rest = value.length > 2 ? value.slice(2) : '';
    return path.join(os.homedir(), rest);
  }
  return value;
}

function resolveConfigFilePath(): string | null {
  const raw = process.env.VRCHAT_MCP_CONFIG_FILE;
  if (!raw) return null;
  const trimmed = raw.trim();
  if (!trimmed) return null;
  return path.isAbsolute(trimmed) ? trimmed : path.resolve(process.cwd(), trimmed);
}

function readConfigFile(filePath: string | null): DeepPartial<ConfigBase> {
  if (!filePath) return {};
  try {
    const content = readFileSync(filePath, 'utf8');
    const parsed: unknown = JSON.parse(content);
    if (!isPlainObject(parsed)) {
      throw new Error('Config file must contain a JSON object.');
    }
    normalizeLegacyConfigFile(parsed);
    return parsed as DeepPartial<ConfigBase>;
  } catch (err) {
    if ((err as { code?: string }).code === 'ENOENT') return {};
    throw err;
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function normalizeLegacyGeneratedToolConfig(value: unknown): void {
  if (!isPlainObject(value)) return;
  if (typeof value.disable === 'boolean') {
    value.enabled = !value.disable;
    delete value.disable;
  }
}

function normalizeLegacyConfigFile(config: Record<string, unknown>): void {
  normalizeLegacyGeneratedToolConfig(config.generatedReadTools);
  normalizeLegacyGeneratedToolConfig(config.generatedWriteTools);
}

function mergeConfig<T>(base: T, override: DeepPartial<T>): T {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return (override ?? base) as T;
  }
  const result: Record<string, unknown> = { ...base };
  for (const [key, value] of Object.entries(override)) {
    if (value === undefined) continue;
    const existing = (base as Record<string, unknown>)[key];
    if (Array.isArray(value)) {
      result[key] = value.slice();
    } else if (isPlainObject(value) && isPlainObject(existing)) {
      result[key] = mergeConfig(existing, value);
    } else {
      result[key] = value;
    }
  }
  return result as T;
}

function applyTemplate(value: string): string {
  return value.replace('{version}', pkg.version ?? '0.0.0');
}

function applyApiEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_API_BASE) {
    overrides.api = { ...overrides.api, baseUrl: env.VRCHAT_MCP_API_BASE };
  }
  if (env.VRCHAT_MCP_USER_AGENT) {
    overrides.api = { ...overrides.api, userAgent: env.VRCHAT_MCP_USER_AGENT };
  }
}

function applySpecEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_SPEC_URL) {
    overrides.spec = { ...overrides.spec, url: env.VRCHAT_MCP_SPEC_URL };
  }
}

function applyLoggingEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_LOG_LEVEL) {
    overrides.logging = { ...overrides.logging, level: env.VRCHAT_MCP_LOG_LEVEL };
  }
}

function applyAuthEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_COOKIE_STORE) {
    overrides.auth = { ...overrides.auth, cookieStore: env.VRCHAT_MCP_COOKIE_STORE };
  }
  if (env.VRCHAT_MCP_COOKIE_FILE) {
    overrides.auth = { ...overrides.auth, cookieFile: env.VRCHAT_MCP_COOKIE_FILE };
  }
}

function applyWriteEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_ALLOW_WRITES !== undefined) {
    overrides.writes = { allow: env.VRCHAT_MCP_ALLOW_WRITES };
  }
}

function applyCacheEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  const cacheOverrides: Partial<ConfigBase['cache']> = {};

  if (env.VRCHAT_MCP_CACHE_ENABLED !== undefined) {
    cacheOverrides.enabled = env.VRCHAT_MCP_CACHE_ENABLED;
  }
  if (Object.keys(cacheOverrides).length > 0) {
    overrides.cache = cacheOverrides as ConfigBase['cache'];
  }
}

function applyPipelineEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  const pipelineOverrides: Partial<ConfigBase['pipeline']> = {};
  if (env.VRCHAT_MCP_PIPELINE_ENABLED !== undefined) {
    pipelineOverrides.enabled = env.VRCHAT_MCP_PIPELINE_ENABLED;
  }
  if (Object.keys(pipelineOverrides).length > 0) {
    overrides.pipeline = pipelineOverrides as ConfigBase['pipeline'];
  }
}

function applyGroupEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_GROUP_ALLOWLIST !== undefined) {
    overrides.groups = { allowlist: env.VRCHAT_MCP_GROUP_ALLOWLIST };
  }
}

function applyUploadEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_UPLOAD_ROOTS !== undefined) {
    overrides.uploads = { allowedRoots: env.VRCHAT_MCP_UPLOAD_ROOTS };
  }
}

function applyToolingEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  if (env.VRCHAT_MCP_ENABLE_RAW_CALL !== undefined) {
    overrides.rawTools = { enabled: env.VRCHAT_MCP_ENABLE_RAW_CALL };
  }

  if (env.VRCHAT_MCP_DISABLE_GENERATED_READ_TOOLS !== undefined) {
    overrides.generatedReadTools = {
      ...overrides.generatedReadTools,
      enabled: !env.VRCHAT_MCP_DISABLE_GENERATED_READ_TOOLS,
    };
  }

  if (env.VRCHAT_MCP_DISABLE_GENERATED_WRITE_TOOLS !== undefined) {
    overrides.generatedWriteTools = {
      ...overrides.generatedWriteTools,
      enabled: !env.VRCHAT_MCP_DISABLE_GENERATED_WRITE_TOOLS,
    };
  }
}

function applyHttpEnvOverrides(overrides: DeepPartial<ConfigBase>, env: EnvValues): void {
  const httpOverrides: Partial<ConfigBase['http']> = {};
  if (env.VRCHAT_MCP_HTTP_PORT !== undefined) {
    httpOverrides.port = env.VRCHAT_MCP_HTTP_PORT;
  }
  if (env.VRCHAT_MCP_HTTP_PATH) {
    httpOverrides.path = env.VRCHAT_MCP_HTTP_PATH;
  }
  if (env.VRCHAT_MCP_HTTP_MAX_SESSIONS !== undefined) {
    httpOverrides.maxSessions = env.VRCHAT_MCP_HTTP_MAX_SESSIONS;
  }
  if (env.VRCHAT_MCP_HTTP_RATE_LIMIT_PER_MINUTE !== undefined) {
    httpOverrides.rateLimitPerMinute = env.VRCHAT_MCP_HTTP_RATE_LIMIT_PER_MINUTE;
  }
  if (env.VRCHAT_MCP_HTTP_SESSION_IDLE_TIMEOUT_MS !== undefined) {
    httpOverrides.sessionIdleTimeoutMs = env.VRCHAT_MCP_HTTP_SESSION_IDLE_TIMEOUT_MS;
  }
  if (Object.keys(httpOverrides).length > 0) {
    overrides.http = httpOverrides as ConfigBase['http'];
  }
}

function readEnvOverrides(): {
  overrides: DeepPartial<ConfigBase>;
} {
  const envInput: Partial<Record<keyof EnvValues, string | undefined>> = {};
  for (const key of ENV_KEYS) {
    envInput[key] = process.env[key];
  }
  let env: EnvValues;
  try {
    env = EnvSchema.parse(envInput);
  } catch (err) {
    if (err instanceof z.ZodError) {
      const issues = err.issues.map((issue) => issue.path.join('.') || 'env');
      throw new Error(`Invalid environment variables: ${issues.join(', ')}`);
    }
    throw err;
  }

  const overrides: DeepPartial<ConfigBase> = {};

  applyApiEnvOverrides(overrides, env);
  applySpecEnvOverrides(overrides, env);
  applyLoggingEnvOverrides(overrides, env);
  applyAuthEnvOverrides(overrides, env);
  applyWriteEnvOverrides(overrides, env);
  applyCacheEnvOverrides(overrides, env);
  applyPipelineEnvOverrides(overrides, env);
  applyGroupEnvOverrides(overrides, env);
  applyUploadEnvOverrides(overrides, env);
  applyToolingEnvOverrides(overrides, env);
  applyHttpEnvOverrides(overrides, env);

  return {
    overrides,
  };
}

function loadBaseConfig(): ConfigBase {
  const configPath = resolveConfigFilePath();
  if (cachedBase && cachedConfigPath === configPath) return cachedBase;
  const fileConfig = readConfigFile(configPath);
  cachedBase = mergeConfig(defaults, fileConfig);
  cachedConfigPath = configPath;
  return cachedBase;
}

export function getConfig(): Config {
  const base = loadBaseConfig();
  const { overrides } = readEnvOverrides();
  const merged = mergeConfig(base, overrides);
  return ConfigSchema.parse(merged);
}

export function resetConfigCacheForTest(): void {
  cachedBase = null;
  cachedConfigPath = null;
}

import { type McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { registerFriendsChangesResource } from './friendsChanges.js';
import { registerFriendsSnapshotResource } from './friendsSnapshot.js';
import { registerResourceSubscriptions } from './subscriptions.js';

